Your expense tracker is below. Add an amount, pick a category and see the monthly total, a category breakdown and what's left of your budget. It tries to save entries on this PC, but I can't promise they survive closing the app.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:14px;background:#fafafa;color:#222}
h2{margin:0 0 10px;font-size:18px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:7px;border:1px solid #bbb;border-radius:6px;font-size:14px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:#c53030;padding:3px 8px}
.card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:10px;margin-bottom:10px}
.big{font-size:22px;font-weight:600}
.bar{height:8px;background:#2b6cb0;border-radius:4px}
.cat{margin:6px 0;font-size:13px}
.item{display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid #eee;font-size:14px}
.over{color:#c53030}.ok{color:#2f855a}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
<div class="row">
<input type="month" id="m">
<input type="number" id="b" placeholder="Budget (₹)" min="0">
</div>
<div class="big" id="total">₹0</div>
<div id="left"></div>
</div>
<div class="card">
<div class="row">
<input type="number" id="a" placeholder="Amount (₹)" min="0" style="width:110px">
<select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option></select>
<input type="text" id="n" placeholder="Note" style="flex:1;min-width:90px">
<button id="add">Add</button>
</div>
</div>
<div class="card"><b>By category</b><div id="cats"></div></div>
<div class="card"><b>Entries</b><div id="list"></div></div>
<script>
var d={items:[],budget:{}};
try{var s=localStorage.getItem("foo-exp");if(s)d=JSON.parse(s)}catch(e){}
var $=function(i){return document.getElementById(i)};
var now=new Date();
$("m").value=now.getFullYear()+"-"+String(now.getMonth()+1).padStart(2,"0");
function fmt(n){return "₹"+Number(n).toLocaleString("en-IN",{maximumFractionDigits:2})}
function save(){try{localStorage.setItem("foo-exp",JSON.stringify(d))}catch(e){}}
function esc(t){return String(t).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function draw(){
var m=$("m").value;
var its=d.items.filter(function(x){return x.m===m});
var tot=its.reduce(function(s,x){return s+x.a},0);
$("total").textContent=fmt(tot);
var bud=d.budget[m]||0;
$("b").value=bud||"";
var l=$("left");
if(bud){var r=bud-tot;l.className=r<0?"over":"ok";l.textContent=r<0?"Over budget by "+fmt(-r):fmt(r)+" left of "+fmt(bud)}else{l.className="";l.textContent="Set a budget to see what's left"}
var by={};its.forEach(function(x){by[x.c]=(by[x.c]||0)+x.a});
var h="";Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
h+='<div class="cat">'+esc(k)+' · '+fmt(by[k])+'<div class="bar" style="width:'+Math.round(by[k]/tot*100)+'%"></div></div>'});
$("cats").innerHTML=h||'<div class="cat">Nothing yet</div>';
var q="";its.slice().reverse().forEach(function(x){
q+='<div class="item"><span>'+esc(x.c)+(x.n?' · '+esc(x.n):'')+'</span><span>'+fmt(x.a)+' <button class="x" data-id="'+x.id+'">×</button></span></div>'});
$("list").innerHTML=q||'<div class="cat">No entries this month</div>';
}
$("add").onclick=function(){
var a=parseFloat($("a").value);if(!(a>0))return;
d.items.push({id:Date.now()+Math.random(),m:$("m").value,a:a,c:$("c").value,n:$("n").value});
$("a").value="";$("n").value="";save();draw()};
$("b").oninput=function(){d.budget[$("m").value]=parseFloat($("b").value)||0;save();
var m=$("m").value,tot=d.items.filter(function(x){return x.m===m}).reduce(function(s,x){return s+x.a},0),bud=d.budget[m],l=$("left");
if(bud){var r=bud-tot;l.className=r<0?"over":"ok";l.textContent=r<0?"Over budget by "+fmt(-r):fmt(r)+" left of "+fmt(bud)}else{l.className="";l.textContent="Set a budget to see what's left"}};
$("m").onchange=draw;
$("list").onclick=function(e){var id=e.target.getAttribute("data-id");if(!id)return;
d.items=d.items.filter(function(x){return String(x.id)!==id});save();draw()};
draw();
</script></body></html>
```

